/**
 * `pnpm gen:ui-css`: compiles scripts/ui/tailwind.css (shadcn/ui's
 * components on Tailwind) into src/web/ui/styles/tailwind.ts, a string the
 * stylesheet includes. The generated file is committed, so a checkout and the
 * image still run heel's source with no build step. `--check` (CI,
 * `pnpm ui-css:drift`) fails when the committed file is stale.
 */
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const target = join(root, "src", "web", "ui", "styles", "tailwind.ts");
const dir = mkdtempSync(join(tmpdir(), "heel-ui-css-"));
try {
  const out = join(dir, "out.css");
  execFileSync(
    join(root, "node_modules", ".bin", "tailwindcss"),
    ["-i", join(root, "scripts", "ui", "tailwind.css"), "-o", out, "--minify"],
    { cwd: root, stdio: ["ignore", "ignore", "inherit"] },
  );
  const css = readFileSync(out, "utf8").trim();
  const source = `// Generated by \`pnpm gen:ui-css\` from scripts/ui/tailwind.css. Don't edit.\nexport const TAILWIND_CSS = ${JSON.stringify(css)};\n`;
  if (process.argv.includes("--check")) {
    const current = readFileSync(target, "utf8");
    if (current !== source) {
      console.error("src/web/ui/styles/tailwind.ts is stale. Run `pnpm gen:ui-css` and commit it.");
      process.exit(1);
    }
    console.error("ui css: up to date");
  } else {
    writeFileSync(target, source);
    console.error(`wrote ${target} (${css.length} bytes)`);
  }
} finally {
  rmSync(dir, { recursive: true, force: true });
}
